  }

  .summary-strip > div:nth-child(4) {
    border-right: 0;
  }

  .summary-strip > div:nth-child(n + 3) {
    border-bottom: 1px solid var(--border);
  }

  .summary-strip > div:last-child {
    border-bottom: 0;
  }

  .filters,
  .port-map-controls,
  .form-grid,
  .host-layout {
    grid-template-columns: 1fr;
  }

  .port-table-header { display: none; }
  .port-assignment { grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; }
  .port-assignment > [role="cell"]::before {
