  .port-assignment { grid-template-columns: 1fr; }
  .port-assignment-notes { grid-column: auto; }
  .path-row { grid-template-columns: 1fr; }
  .site-header {
    padding-top: 1.5rem;
  }

  .header-actions,
  .data-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .filters {
    grid-template-columns: 1fr;
  }

  footer {
    flex-direction: column;
  }
}

